/** A numeric epoch is not an ownership capability for another store's read view. */
class LmdbFeedbackSourceIdentityRegressionTest {
	@Test
	void equalEpochFromAnotherStoreCannotTrainThisStore(@TempDir(cleanup = CleanupMode.NEVER) Path root)
			throws Exception {
		LmdbStore first = store(root.resolve("first"), false);
		LmdbStore second = store(root.resolve("second"), false);
		SailRepository firstRepository = new SailRepository(first);
		SailRepository secondRepository = new SailRepository(second);
		firstRepository.init();
		secondRepository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(first, 30, TimeUnit.SECONDS);
			LmdbTestUtil.awaitPostReadyInitialization(second, 30, TimeUnit.SECONDS);
			for (int attempt = 0; attempt < 128; attempt++) {
				LmdbEvaluationStatistics stats = (LmdbEvaluationStatistics) first.getBackingStore()
						.getEvaluationStatistics();
				long firstRevision = stats.estimatorRuntime().snapshotVersion();
				try (SailDataset dataset = second.getBackingStore().getExplicitSailSource()
						.dataset(IsolationLevels.SNAPSHOT_READ)) {
					SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(second.getValueFactory(), dataset);
					long foreignEpoch = source.getSnapshotEpoch().orElseThrow();
					if (firstRevision == foreignEpoch) {
						LmdbEvaluationStrategy.bindExecutionSnapshot(stats, source, null);
						Filter filter = filter();
						stats.recordFilterOutcome(filter, 30L, 70L);
						assertNull(stats.estimatorRuntime().learnedFilterEvidence(filter),
								"a different store's source must not train this provider, even at the same numeric epoch");
						return;
					}
					if (firstRevision < foreignEpoch) {
						try (var connection = firstRepository.getConnection()) {
							var values = connection.getValueFactory();
							connection.add(values.createIRI("urn:feedback-owner:s:" + attempt),
									values.createIRI("urn:feedback-owner:p"), values.createLiteral(attempt));
						}
					} else {
						try (var connection = secondRepository.getConnection()) {
							connection.setNamespace("feedback", "urn:feedback-owner:" + attempt + ":");
						}
					}
				}
			}
			throw new AssertionError("the fresh stores did not reach a matching epoch within the test watchdog");
		} finally {
			firstRepository.shutDown();
			secondRepository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void sameStoreFeedbackUsesTheLogicalRevisionAcrossMetadataCommits(boolean customFactory,
			@TempDir(cleanup = CleanupMode.NEVER) Path root) throws Exception {
		LmdbStore store = store(root.resolve("store"), !customFactory);
		if (customFactory) {
			store.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory());
		}
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			try (var connection = repository.getConnection()) {
				connection.setNamespace("metadata", "urn:feedback-owner:metadata:");
			}
			try (SailDataset dataset = store.getBackingStore().getExplicitSailSource()
					.dataset(IsolationLevels.SNAPSHOT_READ)) {
				SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
				LmdbEvaluationStatistics stats = (LmdbEvaluationStatistics) store.getBackingStore()
						.getEvaluationStatistics();
				long revision = stats.estimatorRuntime().snapshotVersion();
				assertNotEquals(revision, source.getSnapshotEpoch().orElseThrow(),
						"a metadata-only commit advances the physical epoch without changing the data revision");
				store.getConnectionEvaluationStrategyFactory().createEvaluationStrategy(null, source, stats,
						store.getQueryExecutionPolicy());
				assertTrue(stats.feedbackPublicationAllowed());
				Filter filter = filter();
				stats.recordFilterOutcome(filter, 30L, 70L);
				var evidence = stats.estimatorRuntime().learnedFilterEvidence(filter);
				assertNotNull(evidence, "the paired current source still teaches after factory binding");
				assertEquals(0.3d, evidence.passRatio(), 0.000001d);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStore store(Path path, boolean nativeEvaluation) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(false)
				.setNativeEvaluationEnabled(nativeEvaluation).setFrontierEstimatorMode(FrontierEstimatorMode.SHADOW)
				.setBackgroundRawSamplingEnabled(false).setDirectAdjacencyEnabled(false).setValueOverlayEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		return new LmdbStore(path.toFile(), config);
	}

	private static Filter filter() {
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT ?s WHERE { ?s <urn:feedback-owner:p> ?v FILTER(?v = 5) }", null).getTupleExpr();
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		Filter[] found = new Filter[1];
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter value) {
				if (found[0] == null) {
					found[0] = value;
				}
				super.meet(value);
			}
		});
		return found[0];
	}
}
